/**
 * Generated-code exclusion controls (#1167).
 *
 * Generated files are excluded from analysis by default, but the decision has
 * to be inspectable and overridable: repositories use their own output
 * directories, and an operator may need to analyse generated code on purpose.
 * Every exclusion therefore carries the rule that caused it, and the config is
 * merged with caller-supplied patterns rather than replacing the defaults.
 */

import { isVendoredPath } from "./vendored-dependency-boundaries";

export interface GeneratedCodeExclusionConfig {
  /** Glob-ish path patterns, matched with `*` per segment and `**` per tree. */
  patterns: string[];
  /** Content markers that mark a file as generated. */
  markers: string[];
  /** Whether vendored trees are excluded as well. */
  excludeVendored: boolean;
}

export interface ExclusionDecision {
  excluded: boolean;
  /** Rule that excluded the file, e.g. "pattern:*.pb.go" or "marker:@generated". */
  reason?: string;
}

export interface ExclusionReport {
  included: string[];
  excluded: Array<{ path: string; reason: string }>;
}

export const DEFAULT_GENERATED_CODE_EXCLUSIONS: GeneratedCodeExclusionConfig = {
  patterns: [
    "**/*.min.js",
    "**/*.min.css",
    "**/*.pb.go",
    "**/*.g.dart",
    "**/*.generated.ts",
    "**/dist/**",
    "**/build/**",
    "**/coverage/**",
  ],
  markers: [
    "@generated",
    "code generated by",
    "do not edit",
    "automatically generated",
  ],
  excludeVendored: true,
};

export function mergeExclusionConfig(
  overrides: Partial<GeneratedCodeExclusionConfig> = {},
): GeneratedCodeExclusionConfig {
  return {
    patterns: [
      ...DEFAULT_GENERATED_CODE_EXCLUSIONS.patterns,
      ...(overrides.patterns ?? []),
    ],
    markers: [
      ...DEFAULT_GENERATED_CODE_EXCLUSIONS.markers,
      ...(overrides.markers ?? []),
    ],
    excludeVendored:
      overrides.excludeVendored ?? DEFAULT_GENERATED_CODE_EXCLUSIONS.excludeVendored,
  };
}

/** Convert a path glob into a matcher; `**` spans segments, `*` does not. */
export function patternToRegExp(pattern: string): RegExp {
  const normalized = pattern.replace(/\\/g, "/").replace(/^\.\//, "");
  const escaped = normalized
    .split("/")
    .map((segment) => {
      if (segment === "**") {
        return "(?:.*)";
      }
      return segment
        .replace(/[.+^${}()|[\]\\]/g, "\\$&")
        .replace(/\*/g, "[^/]*");
    })
    .join("/");

  return new RegExp(`^${escaped}$`);
}

/**
 * Decide whether one file is excluded.
 *
 * `contentSample` is optional: path rules apply without reading the file, and
 * marker rules only run when a sample is supplied.
 */
export function isGeneratedCode(
  filePath: string,
  contentSample: string | undefined,
  config: GeneratedCodeExclusionConfig = DEFAULT_GENERATED_CODE_EXCLUSIONS,
): ExclusionDecision {
  const normalized = filePath.replace(/\\/g, "/").replace(/^\.\//, "");

  if (config.excludeVendored && isVendoredPath(normalized)) {
    return { excluded: true, reason: "vendored-boundary" };
  }

  for (const pattern of config.patterns) {
    if (patternToRegExp(pattern).test(normalized)) {
      return { excluded: true, reason: `pattern:${pattern}` };
    }
  }

  if (contentSample) {
    const lower = contentSample.toLowerCase();
    const marker = config.markers.find((candidate) => lower.includes(candidate.toLowerCase()));
    if (marker) {
      return { excluded: true, reason: `marker:${marker}` };
    }
  }

  return { excluded: false };
}

/** Apply the exclusions to a file list, preserving input order. */
export function applyGeneratedCodeExclusions(
  files: ReadonlyArray<{ path: string; content?: string }>,
  config: GeneratedCodeExclusionConfig = DEFAULT_GENERATED_CODE_EXCLUSIONS,
): ExclusionReport {
  const included: string[] = [];
  const excluded: Array<{ path: string; reason: string }> = [];

  for (const file of files) {
    const decision = isGeneratedCode(file.path, file.content, config);
    if (decision.excluded) {
      excluded.push({ path: file.path, reason: decision.reason ?? "unknown" });
    } else {
      included.push(file.path);
    }
  }

  return { included, excluded };
}
